import { createHash, timingSafeEqual } from 'node:crypto';
import type { RequestHandler } from 'express';

export const STAFF_KEY_HEADER = 'x-staff-key';

function digest(value: string): Buffer {
  return createHash('sha256').update(value).digest();
}

/** Admits only requests that present the configured staff API key. */
export function requireStaff(staffApiKey: string): RequestHandler {
  const expected = digest(staffApiKey);
  return (req, res, next) => {
    const presented = req.get(STAFF_KEY_HEADER);
    if (presented === undefined || !timingSafeEqual(digest(presented), expected)) {
      res.status(401).json({
        error: { code: 'UNAUTHORIZED', message: `A valid ${STAFF_KEY_HEADER} header is required` },
      });
      return;
    }
    next();
  };
}

